const gmIntro=g=>`Two fictional ${g[0]} each choose ${g[1]} or ${g[2]}. Payoffs are profits in millions of dollars, written (Firm A, Firm B). Rows are Firm A's choices (${g[1]} on top) and columns are Firm B's choices (${g[1]} on the left). ${[[1,1],[1,2],[2,1],[2,2]].map(([i,j],k)=>`A ${g[i]}, B ${g[j]}: (${g[3][k][0]}, ${g[3][k][1]}).`).join(' ')}`;
const gmtab=g=>mat(`${g[0][0].toUpperCase()+g[0].slice(1)} (fictional), payoffs (A, B) in millions`,[g[1],g[2]],[g[1],g[2]],g[3]);
/* dominant strategy for a player (0 = Firm A rows, 1 = Firm B columns): the choice that pays more whatever the rival does, else none */
const domOf=(g,pl)=>{const c=g[3],at=(me,you)=>pl?c[2*you+me][1]:c[2*me+you][0];for(const me of [0,1])if([0,1].every(you=>at(me,you)>at(1-me,you)))return g[1+me];return 'none';};
const neOf=g=>{const c=g[3],out=[];for(let i=0;i<2;i++)for(let j=0;j<2;j++)if(c[2*i+j][0]>=c[2*(1-i)+j][0]&&c[2*i+j][1]>=c[2*i+(1-j)][1])out.push(2*i+j);return out;};
